package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Every problem is collected and reported together in one {@link ConfigException}. Nothing falls back to a
 * default when a value is wrong: a missing optional key uses its default, a present key must be valid.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url", "api.token", "worker.threads", "queue.capacity",
            "retry.max-attempts", "request.timeout", "metrics.enabled");
    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();
        checkKeys(properties, problems);
        ServiceConfig config = new ServiceConfig(
                uri(properties, "upstream.url", problems),
                required(properties, "api.token", problems),
                intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems),
                intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems),
                intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems),
                duration(properties, "request.timeout", problems),
                bool(properties, "metrics.enabled", problems));
        if (!problems.isEmpty()) {
            throw new ConfigException(report(file, problems));
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("configuration file " + file + " was not found");
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("configuration file " + file + " cannot be read: " + e.getMessage());
        }
        return properties;
    }

    private static String report(Path file, List<String> problems) {
        StringBuilder text = new StringBuilder("invalid configuration in " + file + ", the relay will not start:");
        for (String problem : problems) {
            text.append("\n  - ").append(problem);
        }
        return text.toString();
    }

    private static void checkKeys(Properties properties, List<String> problems) {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + " is not a known key (check the spelling)");
            }
        }
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, String key, List<String> problems) {
        String raw = required(properties, key, problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (uri.isAbsolute() && uri.getHost() != null) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add(key + " must be an absolute URL such as https://host/path (got '" + raw + "')");
        return null;
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number of at least " + minimum + " (got '" + raw.trim() + "')");
        return defaultValue;
    }

    private static Duration duration(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                return switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a whole number followed by ms, s or m (got '" + raw.trim() + "')");
        return DEFAULT_REQUEST_TIMEOUT;
    }

    private static boolean bool(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (value.equalsIgnoreCase("true")) {
            return true;
        }
        if (value.equalsIgnoreCase("false")) {
            return false;
        }
        problems.add(key + " must be true or false (got '" + value + "')");
        return false;
    }
}

